E3A.css:
[data-ui-unit="E3A"].day-group h2 {
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
  margin: 0;
}

[data-ui-unit="E3A"].day-group span {
  font-weight: 500;
  color: var(--muted, #666);
}

[data-ui-unit="E3A"] .place-row {
  margin-top: 16px;
}

[data-ui-unit="E3A"] .place-card {
  border: 1px solid var(--border, #e8e8e8);
  border-radius: 6px;
}

[data-ui-unit="E3A"] .place-title {
  font-size: 14px;
  line-height: 1.4;
  font-weight: 700;
}

[data-ui-unit="E3A"] .place-type {
  font-size: 14px;
  line-height: 1.4;
  font-weight: 500;
  color: var(--muted, #666);
}

E3B.css:
[data-ui-unit="E3B"] > h2 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  margin: 0;
}
[data-ui-unit="E3B"] > h2 span {
  font-weight: 500;
  color: var(--muted, #666);
}
[data-ui-unit="E3B"] > .place-row:first-of-type {
  margin-top: 16px;
}
[data-ui-unit="E3B"] > .place-row:not(:first-of-type) {
  margin-top: 18px;
}
[data-ui-unit="E3B"] .place-card {
  border: 1px solid var(--border, #e8e8e8);
  border-radius: 6px;
}
[data-ui-unit="E3B"] .place-title {
  font-weight: 700;
  font-size: 14px;
  line-height: 1.4;
}
[data-ui-unit="E3B"] .place-region {
  font-weight: 700;
  font-size: 14px;
  line-height: 1.4;
  margin-top: 2px;
}
[data-ui-unit="E3B"] .place-type {
  font-weight: 500;
  color: var(--muted, #666);
  font-size: 14px;
  line-height: 1.4;
  margin-top: 2px;
}

E3C.css:
[data-ui-unit="E3C"] > h2 {
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
  margin-bottom: 16px;
}

[data-ui-unit="E3C"] > h2 span {
  font-weight: 500;
  color: var(--muted, #666);
}

[data-ui-unit="E3C"] .partial-slot {
  margin-left: 31px;
  height: 18px;
  overflow: hidden;
}

[data-ui-unit="E3C"] .partial-card {
  border: 1px solid var(--border, #e8e8e8);
  border-radius: 6px;
  height: 100%;
  display: flex;
  align-items: flex-start;
}

[data-ui-unit="E3C"] .partial-card img {
  width: 96px;
  height: 17px;
  display: block;
  object-fit: cover;
}

@media (max-width: 360px) {
  [data-ui-unit="E3C"] .partial-card img {
    width: 72px;
  }
}

E4.css:
[data-ui-unit="E4"] {
  width: 100%;
}
[data-ui-unit="E4"].trip-footer {
  display: flex;
  justify-content: center;
  width: 100%;
}
[data-ui-unit="E4"] button {
  display: block;
  width: 100%;
  min-height: 56px;
  border-radius: 12px;
  background-color: #bdbdbd;
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.2;
  border: none;
  padding: 0;
}
[data-ui-unit="E4"] button:disabled {
  background-color: #bdbdbd;
  color: #fff;
  opacity: 1;
  cursor: not-allowed;
}
